using System;
using System.Diagnostics;
using System.IO;
using System.Text;
using System.Threading;
using System.Windows.Forms;
using Microsoft.Win32;

static class MosslightUninstaller {
 const string ProductKey=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\MosslightFarm";
 static bool Chinese=System.Globalization.CultureInfo.CurrentUICulture.Name.StartsWith("zh");
 static string T(string zh,string en){return Chinese?zh:en;}
 static string Root { get { return Path.GetFullPath(AppDomain.CurrentDomain.BaseDirectory).TrimEnd(Path.DirectorySeparatorChar); } }
 static string Game { get { return Path.Combine(Root,"MosslightFarm.exe"); } }
 [STAThread] static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool quiet=Array.Exists(args,a=>a=="--quiet");try{ValidateRoot();if(args.Length>0&&args[0]=="--self-check"){if(!File.Exists(Game)||!File.Exists(Path.Combine(Root,"MosslightFarmUninstall.exe")))throw new FileNotFoundException("Install is incomplete.");return;}if(!quiet&&MessageBox.Show(T("要卸载苔光农场吗？\n农场存档会保留。","Uninstall Mosslight Farm?\nYour farm saves will be kept."),T("卸载苔光农场","Uninstall Mosslight Farm"),MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;DisableStartup();StopGame();StartCleanup();if(!quiet)MessageBox.Show(T("卸载程序已启动。游戏文件将安全移除，存档会保留。","Uninstall started. The game files will be removed; your saves will be kept."),T("苔光农场","Mosslight Farm"),MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){WriteLog(ex.ToString());if(!quiet)MessageBox.Show(T("无法完成卸载：","Could not complete uninstall:")+"\n"+ex.Message,T("苔光农场卸载","Mosslight Farm Uninstall"),MessageBoxButtons.OK,MessageBoxIcon.Error);Environment.ExitCode=1;}}
 static void ValidateRoot(){string parent=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Applications","MosslightFarm");if(!String.Equals(Path.GetDirectoryName(Root).TrimEnd(Path.DirectorySeparatorChar),parent.TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Refusing to remove a folder outside the Mosslight Farm install location.");if((File.GetAttributes(Root)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("The install folder is a reparse point.");}
 static void DisableStartup(){if(!File.Exists(Game))return;using(Process p=Process.Start(new ProcessStartInfo(Game,"--set-autostart off"){WorkingDirectory=Root,UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){if(!p.WaitForExit(30000)||p.ExitCode!=0)throw new InvalidOperationException("Could not turn off automatic startup.");}}
 static void StopBuild(string flavor){EventWaitHandle quit;if(EventWaitHandle.TryOpenExisting("Local\\MosslightFarm-"+flavor+"-Quit",out quit))using(quit)quit.Set();try{using(Mutex mutex=Mutex.OpenExisting("MosslightFarm-"+flavor)){bool acquired=false;try{try{acquired=mutex.WaitOne(20000);}catch(AbandonedMutexException){acquired=true;}if(!acquired)throw new InvalidOperationException("The farm is still saving. Close it and retry the uninstall.");}finally{if(acquired)mutex.ReleaseMutex();}}}catch(WaitHandleCannotBeOpenedException){}}
 static void StopGame(){StopBuild("Player");StopBuild("Maintenance");}
 static void StartCleanup(){string target=Root;string encoded=Convert.ToBase64String(Encoding.UTF8.GetBytes(target));string scriptPath=Path.Combine(Path.GetTempPath(),"MosslightFarm-uninstall-"+Guid.NewGuid().ToString("N")+".ps1");string script="$ErrorActionPreference = 'Stop'\r\n"+"$target = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('"+encoded+"'))\r\n"+"$ownerId = "+Process.GetCurrentProcess().Id+"\r\n"+"$log = Join-Path $env:TEMP 'MosslightFarm-uninstall.log'\r\n"+"try {\r\n"+"  $deadline = [DateTime]::UtcNow.AddSeconds(60)\r\n"+"  while ((Get-Process -Id $ownerId -ErrorAction SilentlyContinue) -and [DateTime]::UtcNow -lt $deadline) { Start-Sleep -Milliseconds 200 }\r\n"+"  if (Get-Process -Id $ownerId -ErrorAction SilentlyContinue) { throw 'Uninstaller process did not exit.' }\r\n"+"  if (Test-Path -LiteralPath $target) { Remove-Item -LiteralPath $target -Recurse -Force -ErrorAction Stop }\r\n"+"  if (Test-Path -LiteralPath $target) { throw 'Install folder is still present.' }\r\n"+"  $relativeKey = 'Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\MosslightFarm'\r\n"+"  $registryKey = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($relativeKey, $true)\r\n"+"  if ($registryKey) { foreach ($value in $registryKey.GetValueNames()) { $registryKey.DeleteValue($value, $false) }; $children = $registryKey.SubKeyCount; $registryKey.Close(); if ($children -eq 0) { [Microsoft.Win32.Registry]::CurrentUser.DeleteSubKey($relativeKey, $false) } }\r\n"+"} catch { Add-Content -LiteralPath $log -Value ((Get-Date -Format o) + ' ' + $_.ToString()); exit 1 }\r\n"+"$container = [IO.Path]::GetDirectoryName($target)\r\n"+"try { if ((Test-Path -LiteralPath $container) -and @(Get-ChildItem -LiteralPath $container -Force).Count -eq 0) { Remove-Item -LiteralPath $container -Force } } catch { Add-Content -LiteralPath $log -Value ((Get-Date -Format o) + ' ' + $_.ToString()) }\r\n"+"$desktop = Join-Path ([Environment]::GetFolderPath([Environment+SpecialFolder]::DesktopDirectory)) 'Mosslight Farm.lnk'\r\n"+"try { if (Test-Path -LiteralPath $desktop) { Remove-Item -LiteralPath $desktop -Force } } catch { Add-Content -LiteralPath $log -Value ((Get-Date -Format o) + ' ' + $_.ToString()) }\r\n"+"$menu = Join-Path ([Environment]::GetFolderPath([Environment+SpecialFolder]::Programs)) 'Mosslight Farm'\r\n"+"foreach ($name in @('Mosslight Farm.lnk','Mosslight Management.lnk')) { try { $link = Join-Path $menu $name; if (Test-Path -LiteralPath $link) { Remove-Item -LiteralPath $link -Force } } catch { Add-Content -LiteralPath $log -Value ((Get-Date -Format o) + ' ' + $_.ToString()) } }\r\n"+"try { if ((Test-Path -LiteralPath $menu) -and @(Get-ChildItem -LiteralPath $menu -Force).Count -eq 0) { Remove-Item -LiteralPath $menu -Force } } catch { Add-Content -LiteralPath $log -Value ((Get-Date -Format o) + ' ' + $_.ToString()) }\r\n"+"try { Remove-Item -LiteralPath $PSCommandPath -Force } catch {}\r\n";File.WriteAllText(scriptPath,script,new UTF8Encoding(true));string powershell=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell\\v1.0\\powershell.exe");ProcessStartInfo info=new ProcessStartInfo(powershell,"-NoLogo -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \""+scriptPath+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};Process helper=Process.Start(info);if(helper==null)throw new InvalidOperationException("Could not start the uninstall cleanup.");if(helper.WaitForExit(1500))throw new InvalidOperationException("The uninstall cleanup exited before it could remove the game.");}
 static void WriteLog(string text){try{File.AppendAllText(Path.Combine(Path.GetTempPath(),"MosslightFarm-uninstall.log"),DateTime.Now.ToString("o")+" "+text+Environment.NewLine);}catch{}}
}
